{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "The proportion of people who will remain asymptomatic throughout the course of infection with severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), the cause of coronavirus disease 2019 (COVID-19), is not known. Studies that assess people at just one time point will overestimate the proportion of true asymptomatic infection because those who go on to develop COVID-19 symptoms will be wrongly classified as asymptomatic rather than presymptomatic.",
      "reason": "The text explicitly describes the current state of knowledge (that the proportion of asymptomatic infection is unknown) and the important uncertainty/methodological issue (overestimation due to single time-point assessment)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "The amount, and infectiousness, of asymptomatic SARS-CoV-2 infection will determine what kind of measures will prevent transmission most effectively.",
      "reason": "The text explains the importance of the review by linking the need to understand asymptomatic infection to the development of effective transmission prevention measures."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_20",
      "quote": "We found three systematic reviews, which reported similar summary estimates from meta-analysis of studies published up to May [119-121]... In comparison with other reviews, rather than restricting inclusion, we give a comprehensive overview of studies with adequate follow-up, with assessment of risks of bias and exploration of heterogeneity (S2-S7 Figs).",
      "reason": "The authors identify existing systematic reviews and explain the need for their current review by highlighting their methodological differences (comprehensive overview, assessment of risk of bias, exploration of heterogeneity)."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a systematic review of the proportion of asymptomatic SARS-CoV-2 infections, not a review of intervention effects; therefore, a mechanism of action is not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is not a review of complex interventions or delivery contexts; therefore, a logic model is not applicable."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "The objectives of this study were to address three questions: (1) Amongst people who become infected with SARS-CoV-2, what proportion do not experience symptoms at all during their infection? (2) Amongst people with SARS-CoV-2 infection who are asymptomatic when diagnosed, what proportion will develop symptoms later? (3) What proportion of SARS-CoV-2 transmission is accounted for by people who are either asymptomatic throughout infection or presymptomatic?",
      "reason": "The manuscript explicitly lists the three review questions/objectives in the Introduction section."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a systematic review of prevalence/proportions (asymptomatic SARS-CoV-2 infection), not a review of intervention effects (e.g., comparing treatments or interventions). Therefore, PICO is not the appropriate framework for these specific objectives."
    }
  ],
  "confidence": 100
}

{
